/* TUNIATLAS_AUTH_TRANSLATION_REPAIR_V1 */
(function(){
  if (window.TA_AUTH_TRANSLATION_REPAIR_V1) return;
  window.TA_AUTH_TRANSLATION_REPAIR_V1 = true;

  const MAP = {
    "Connexion": "Sign in",
    "Créer un compte": "Create account",
    "Mot de passe oublié ?": "Forgot password?",
    "Password forgotten?": "Mot de passe oublié ?",
    "Saisissez l’adresse e-mail associée à votre compte, et nous vous enverrons un lien pour réinitialiser votre mot de passe.": "Enter the email address associated with your account and we will send you a password reset link.",
    "Adresse email": "Email address",
    "Réinitialiser le mot de passe": "Reset password",
    "Retour à la connexion": "Back to sign in",
    "Pas encore de compte ? Créer un compte": "No account yet? Create account",
    "Déjà un compte ? Connexion": "Already have an account? Sign in",
    "Continuer avec Google": "Continue with Google",
    "Continuer avec GitHub": "Continue with GitHub",
    "Email": "Email",
    "Mot de passe": "Password",
    "Confirmer le mot de passe": "Verify password",
    "Répéter le mot de passe": "Repeat password",
    "Mot de passe requis.": "Password required.",
    "Email valide requis.": "Valid email required.",
    "Minimum 6 caractères.": "Minimum 6 characters.",
    "Les mots de passe ne correspondent pas.": "Passwords do not match.",
    "Mots de passe identiques.": "Passwords match.",
    "Réinitialisation envoyée": "Password reset sent",
    "Vérifiez votre boîte mail.": "Check your inbox.",
    "Changer le mot de passe": "Change password",
    "Nouveau mot de passe": "New password",
    "Confirmer le nouveau mot de passe": "Confirm new password",
    "Enregistrer le nouveau mot de passe": "Save new password"
  };

  const REVERSE = {};
  Object.entries(MAP).forEach(([fr, en]) => {
    if (en && !REVERSE[en]) REVERSE[en] = fr;
  });

  function clean(text){
    return (text || "").replace(/\s+/g, " ").trim();
  }

  function lang(){
    return localStorage.getItem("ta-lang") || document.documentElement.lang || "fr";
  }

  function translateValue(text, currentLang){
    const key = clean(text);
    if (!key) return text;

    // Auth source is mixed: some text starts French, some starts English.
    if (currentLang === "en") {
      return MAP[key] || key;
    }
    return REVERSE[key] || key;
  }

  function translateAuthPage(){
    const root = document.querySelector("main.auth-v16");
    if (!root) return;

    const currentLang = lang();

    root.querySelectorAll("[data-fr][data-en]").forEach((el) => {
      const value = currentLang === "fr" ? el.getAttribute("data-fr") : el.getAttribute("data-en");
      if (value) el.textContent = value;
    });

    root.querySelectorAll("[data-i18n]").forEach((el) => {
      const key = clean(el.getAttribute("data-i18n"));
      if (!key) return;

      if (currentLang === "fr" && typeof TA_TRANSLATIONS !== "undefined") {
        el.textContent = TA_TRANSLATIONS[key] || REVERSE[key] || key;
      } else {
        el.textContent = key;
      }
    });

    const selector = [
      "h1",
      "h2",
      "h3",
      "label",
      "button",
      "a",
      ".small",
      ".error",
      ".success"
    ].join(",");

    root.querySelectorAll(selector).forEach((el) => {
      if (el.childElementCount > 0 && !el.matches("button")) return;

      const current = clean(el.textContent);
      const next = translateValue(current, currentLang);
      if (next && next !== current) el.textContent = next;
    });

    root.querySelectorAll("input[placeholder]").forEach((el) => {
      const current = clean(el.getAttribute("placeholder"));
      const next = translateValue(current, currentLang);
      if (next && next !== current) el.setAttribute("placeholder", next);
    });

    const title = clean(document.title.replace(" - TuniAtlas", ""));
    const translatedTitle = translateValue(title, currentLang);
    if (translatedTitle && translatedTitle !== title) {
      document.title = translatedTitle + " - TuniAtlas";
    }
  }

  window.TA_AUTH_TRANSLATE_NOW = translateAuthPage;

  const previousApplyLanguage = window.applyLanguage;
  if (typeof previousApplyLanguage === "function" && !previousApplyLanguage.__authRepairWrapped) {
    window.applyLanguage = function(nextLang){
      const result = previousApplyLanguage.apply(this, arguments);
      setTimeout(translateAuthPage, 0);
      setTimeout(translateAuthPage, 120);
      return result;
    };
    window.applyLanguage.__authRepairWrapped = true;
  }

  document.addEventListener("DOMContentLoaded", function(){
    setTimeout(translateAuthPage, 0);
    setTimeout(translateAuthPage, 150);
    setTimeout(translateAuthPage, 500);
  });

  window.addEventListener("load", function(){
    setTimeout(translateAuthPage, 0);
    setTimeout(translateAuthPage, 250);
  });

  document.addEventListener("click", function(e){
    if (e.target.closest("[data-lang-toggle]")) {
      setTimeout(translateAuthPage, 60);
      setTimeout(translateAuthPage, 200);
      setTimeout(translateAuthPage, 500);
    }
  }, true);
})();
